from datetime import datetime


def parse_statement(text):
    months = {
        "Jan": 1,
        "Feb": 2,
        "Mar": 3,
        "Apr": 4,
        "May": 5,
        "Jun": 6,
        "Jul": 7,
        "Aug": 8,
        "Sep": 9,
        "Oct": 10,
        "Nov": 11,
        "Dec": 12,
    }

    results = []

    for line in text.splitlines():
        if not line.strip():
            continue

        parts = line.split(",")
        if len(parts) != 3:
            continue

        date_str, desc_str, amt_str = parts[0].strip(), parts[1].strip(), parts[2].strip()

        # Parse date
        parsed_date = None
        # Try DD/MM/YYYY
        try:
            dt = datetime.strptime(date_str, "%d/%m/%Y")
            parsed_date = dt.strftime("%Y-%m-%d")
        except ValueError:
            pass

        # Try YYYY-MM-DD
        if not parsed_date:
            try:
                dt = datetime.strptime(date_str, "%Y-%m-%d")
                parsed_date = dt.strftime("%Y-%m-%d")
            except ValueError:
                pass

        # Try D Mon YYYY
        if not parsed_date:
            try:
                d_parts = date_str.split()
                if len(d_parts) == 3 and d_parts[1] in months:
                    day = int(d_parts[0])
                    month = months[d_parts[1]]
                    year = int(d_parts[2])
                    dt = datetime(year, month, day)
                    parsed_date = dt.strftime("%Y-%m-%d")
            except (ValueError, KeyError, IndexError):
                pass

        if not parsed_date:
            continue

        # Parse amount
        is_negative = False
        clean_amt = amt_str

        if clean_amt.startswith("(") and clean_amt.endswith(")"):
            is_negative = True
            clean_amt = clean_amt[1:-1].strip()
        elif clean_amt.endswith(" DR") or clean_amt.endswith(" dr"):
            is_negative = True
            clean_amt = clean_amt[:-3].strip()

        clean_amt = clean_amt.replace("₹", "").replace("$", "").replace(",", "").strip()

        try:
            amount = float(clean_amt)
            if is_negative:
                amount = -amount
        except ValueError:
            continue

        results.append(
            {"date": parsed_date, "description": desc_str, "amount": amount}
        )

    return sorted(results, key=lambda x: x["date"])

