    for start, end, prio in res[1:]:
        p_start, p_end, p_prio = coalesced[-1]
        if p_end == start and p_prio == prio:
            coalesced[-1] = (p_start, end, prio)
        else:
            coalesced.append((start, end, prio))

    return coalesced

