import csv
from datetime import datetime
import io
import re


def parse_ledger(text):
    MONTHS = {
        "Jan": 1,
        "Feb": 2,
        "Mar": 3,
        "Apr": 4,
        "May": 5,
        "Jun": 6,
        "Jul": 7,
        "Aug": 8,
        "Sep": 9,
        "Oct": 10,
        "Nov": 11,
        "Dec": 12,
    }
    RATES = {"INR": 1.0, "USD": 83.5, "EUR": 90.25}

    results = []
    seen = set()

    for row in csv.reader(io.StringIO(text)):
        if not row or not any(row):
            continue
        if len(row) != 4:
            continue

        date_str, desc_str, amt_str, curr_str = [c.strip() for c in row]
        desc_str = desc_str.strip()

        # Currency
        currency = curr_str.upper()
        if currency not in RATES:
            continue

        # Date normalization
        norm_date = None
        # 1. DD/MM/YYYY
        m = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", date_str)
        if m:
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                norm_date = datetime(y, mo, d).strftime("%Y-%m-%d")
            except ValueError:
                pass

        # 2. YYYY-MM-DD
        if not norm_date:
            m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", date_str)
            if m:
                y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                try:
                    norm_date = datetime(y, mo, d).strftime("%Y-%m-%d")
                except ValueError:
                    pass

        # 3. D Mon YYYY (e.g. 3 Jan 2026)
        if not norm_date:
            m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$", date_str)
            if m:
                d, mon_str, y = int(m.group(1)), m.group(2).capitalize(), int(m.group(3))
                if mon_str in MONTHS:
                    try:
                        norm_date = datetime(y, MONTHS[mon_str], d).strftime("%Y-%m-%d")
                    except ValueError:
                        pass

        # 4. Mon D, YYYY (e.g. Jan 3, 2026)
        if not norm_date:
            m = re.match(r"^([A-Za-z]{3})\s+(\d{1,2}),\s+(\d{4})$", date_str)
            if m:
                mon_str, d, y = m.group(1).capitalize(), int(m.group(2)), int(m.group(3))
                if mon_str in MONTHS:
                    try:
                        norm_date = datetime(y, MONTHS[mon_str], d).strftime("%Y-%m-%d")
                    except ValueError:
                        pass

        if not norm_date:
            continue

        # Amount parsing
        a_clean = amt_str.replace(" ", "")
        is_negative = False
        if a_clean.startswith("(") and a_clean.endswith(")"):
            is_negative = True
            a_clean = a_clean[1:-1]
        elif a_clean.endswith("DR") or a_clean.endswith("dr"):
            is_negative = True
            a_clean = a_clean[:-2]

        # Strip symbols
        for sym in ["₹", "$", "€"]:
            a_clean = a_clean.replace(sym, "")

        a_clean = a_clean.replace(",", "")

        try:
            val = float(a_clean)
        except ValueError:
            continue

        if is_negative:
            val = -val

        amount_inr = round(val * RATES[currency], 2)

        key = (norm_date, desc_str, amount_inr)
        if key in seen:
            continue
        seen.add(key)

        results.append(
            {"date": norm_date, "description": desc_str, "amount_inr": amount_inr}
        )

    results.sort(key=lambda x: (x["date"], -abs(x["amount_inr"])))
    return results

import csv
from datetime import datetime
import io


def parse_ledger(text):
    MONTHS = {
        "Jan": 1,
        "Feb": 2,
        "Mar": 3,
        "Apr": 4,
        "May": 5,
        "Jun": 6,
        "Jul": 7,
        "Aug": 8,
        "Sep": 9,
        "Oct": 10,
        "Nov": 11,
        "Dec": 12,
    }
    EXCHANGE_RATES = {"INR": 1.0, "USD": 83.5, "EUR": 90.25}

    def parse_date(date_str):
        date_str = date_str.strip()
        # DD/MM/YYYY
        if (
            len(date_str) == 10
            and date_str[2] == "/"
            and date_str[5] == "/"
            and date_str[:2].isdigit()
            and date_str[3:5].isdigit()
            and date_str[6:].isdigit()
        ):
            try:
                dt = datetime.strptime(date_str, "%d/%m/%Y")
                return dt.strftime("%Y-%m-%d")
            except ValueError:
                pass

        # YYYY-MM-DD
        if (
            len(date_str) == 10
            and date_str[4] == "-"
            and date_str[7] == "-"
            and date_str[:4].isdigit()
            and date_str[5:7].isdigit()
            and date_str[8:].isdigit()
        ):
            try:
                dt = datetime.strptime(date_str, "%Y-%m-%d")
                return dt.strftime("%Y-%m-%d")
            except ValueError:
                pass

        # D Mon YYYY (e.g. "3 Jan 2026")
        parts = date_str.split()
        if len(parts) == 3 and parts[1] in MONTHS:
            try:
                day = int(parts[0])
                month = MONTHS[parts[1]]
                year = int(parts[2])
                dt = datetime(year, month, day)
                return dt.strftime("%Y-%m-%d")
            except ValueError:
                pass

        # Mon D, YYYY (e.g. "Jan 3, 2026")
        if len(parts) == 3 and parts[0] in MONTHS and parts[1].endswith(","):
            try:
                month = MONTHS[parts[0]]
                day = int(parts[1][:-1])
                year = int(parts[2])
                dt = datetime(year, month, day)
                return dt.strftime("%Y-%m-%d")
            except ValueError:
                pass

        return None

    def parse_amount(amt_str, currency):
        amt_str = amt_str.strip()
        negative = False
        if amt_str.startswith("(") and amt_str.endswith(")"):
            negative = True
            amt_str = amt_str[1:-1].strip()
        elif amt_str.endswith(" DR") or amt_str.endswith(" dr"):
            negative = True
            amt_str = amt_str[:-3].strip()

        # Remove currency symbols if present
        for sym in ["₹", "$", "€"]:
            if amt_str.startswith(sym):
                amt_str = amt_str[len(sym) :].strip()
                break

        # Remove thousands commas
        amt_str = amt_str.replace(",", "")

        try:
            val = float(amt_str)
            if negative:
                val = -val
            rate = EXCHANGE_RATES.get(currency, 1.0)
            return round(val * rate, 2)
        except ValueError:
            return None

    results = []
    seen = set()

    f = io.StringIO(text.strip())
    reader = csv.reader(f)

    for row in reader:
        if not row or all(not field.strip() for field in row):
            continue
        if len(row) != 4:
            continue

        date_raw, desc_raw, amt_raw, curr_raw = row[0], row[1], row[2], row[3]

        norm_date = parse_date(date_raw)
        if not norm_date:
            continue

        currency = curr_raw.strip()
        if currency not in EXCHANGE_RATES:
            continue

        amount_inr = parse_amount(amt_raw, currency)
        if amount_inr is None:
            continue

        description = desc_raw.strip()

        key = (norm_date, description, amount_inr)
        if key not in seen:
            seen.add(key)
            results.append(
                {
                    "date": norm_date,
                    "description": description,
                    "amount_inr": amount_inr,
                }
            )

    results.sort(key=lambda x: (x["date"], -abs(x["amount_inr"])))
    return results

