from datetime import datetime
from zoneinfo import ZoneInfo


def elapsed_seconds(tz_name: str, start: str, end: str) -> float:
    tz = ZoneInfo(tz_name)

    def parse_local_time(dt_str: str) -> datetime:
        naive = datetime.strptime(dt_str, "%Y-%m-%d %H:%M:%S")
        try:
            return naive.replace(tzinfo=tz, fold=0)
        except Exception:
            pass

        try:
            return naive.replace(tzinfo=ZoneInfo("UTC")) - tz.utcoffset(
                naive.replace(tzinfo=ZoneInfo("UTC"))
            )
        except Exception:
            pass

        # Fallback for spring-forward gap using offset before the jump
        dt_utc_guess = naive.replace(tzinfo=ZoneInfo("UTC"))
        offset = None
        for delta_minutes in (-1, -2, -5, -10, -30, -60, -120):
            from datetime import timedelta

            test_utc = dt_utc_guess + timedelta(minutes=delta_minutes)
            off = tz.utcoffset(test_utc)
            if off is not None:
                offset = off
                break
        if offset is None:
            offset = tz.utcoffset(dt_utc_guess)

        return naive.replace(tzinfo=ZoneInfo("UTC")) - offset

    dt_start = parse_local_time(start)
    dt_end = parse_local_time(end)

    return (dt_end - dt_start).total_seconds()

from datetime import datetime
from zoneinfo import ZoneInfo


def elapsed_seconds(tz_name, start, end):
    tz = ZoneInfo(tz_name)

    def parse_dt(s):
        dt_naive = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        try:
            return dt_naive.replace(tzinfo=tz, fold=0)
        except Exception:
            # Handle spring-forward (gap): fold might not apply, or ambiguous.
            # But ZoneInfo.replace with fold handles ambiguity. For gaps,
            # we need the offset before the jump.
            pass

        # Try standard resolution first
        try:
            return dt_naive.astimezone(tz)
        except Exception:
            pass

        # If it raises or fails due to a gap, construct using pre-transition offset.
        # We can test by shifting slightly backward or using standard datetime fold/gap logic.
        # Actually, python's zoneinfo handles gaps by raising ValueError or folding.
        # The prompt specifies:
        # - Spring-forward (gap): resolve using UTC offset immediately BEFORE the jump.
        # - Fall-back (repeated): resolve to the FIRST (fold=0).
        try:
            return dt_naive.replace(tzinfo=tz, fold=0)
        except ValueError:
            # This is a nonexistent time (spring forward gap).
            # Subtract a small delta (e.g., 1 hour) to find the offset before the jump.
            dt_shifted = dt_naive - datetime.resolution * 3600 * 1000000  # 1 hour earlier
            # Actually, standard timedelta is easier:
            from datetime import timedelta

            dt_shifted = dt_naive - timedelta(hours=1)
            offset_before = dt_shifted.replace(tzinfo=tz).utcoffset()
            # Apply that offset to get the correct UTC time, then attach tz
            # Better yet, convert naive to UTC using offset_before, then convert to tz?
            # A datetime with fixed offset:
            from datetime import timezone

            dt_fixed = dt_naive.replace(tzinfo=timezone(offset_before))
            return dt_fixed.astimezone(tz)

    dt_start = parse_dt(start)
    dt_end = parse_dt(end)

    return (dt_end - dt_start).total_seconds()

