from datetime import datetime
from zoneinfo import ZoneInfo


def elapsed_seconds(tz_name, start, end):
    tz = ZoneInfo(tz_name)

    def parse_dt(s):
        dt_naive = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        try:
            return dt_naive.replace(tzinfo=tz, fold=0)
        except Exception:
            pass

        try:
            dt_aware = dt_naive.replace(tzinfo=tz)
            if dt_aware.tzinfo.utcoffset(dt_aware) is not None:
                return dt_aware
        except Exception:
            pass

        try:
            dt_aware = tz.fromutc(dt_naive)
            return dt_aware
        except Exception:
            pass

        try:
            dt_plus = (dt_naive - datetime(1970, 1, 1)).total_seconds()
            dt_aware = datetime.fromtimestamp(dt_plus, tz)
            return dt_aware
        except Exception:
            pass

        return dt_naive.replace(tzinfo=tz)

    try:
        dt_start = datetime.strptime(start, "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=tz, fold=0
        )
    except (ValueError, AttributeError):
        dt_start = parse_dt(start)

    try:
        dt_end = datetime.strptime(end, "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=tz, fold=1
        )
    except (ValueError, AttributeError):
        dt_end = parse_dt(end)

    return (dt_end - dt_start).total_seconds()

import unicodedata

def truncate_graphemes(s, n):
    if not s:
        return s

    clusters = []
    current_cluster = []
    join_next = False

    for cp in s:
        is_mn = (unicodedata.category(cp) == "Mn")
        is_zwj = (cp == "\u200D")

        if not current_cluster:
            # First code point in a cluster
            current_cluster.append(cp)
            join_next = is_zwj
        else:
            if join_next:
                # ZWJ forces this code point (and its following Mn) into the current cluster
                current_cluster.append(cp)
                join_next = is_zwj
            elif is_mn:
                # Combining mark always attaches to the current cluster
                current_cluster.append(cp)
            else:
                # Normal code point starts a new cluster
                clusters.append("".join(current_cluster))
                current_cluster = [cp]
                join_next = is_zwj

    if current_cluster:
        clusters.append("".join(current_cluster))

    if len(clusters) <= n:
        return s
    else:
        return "".join(clusters[:n]) + "..."

